const COURSE_LESSON_HTML = {
  "kurssArticlesLesson": "\n  <h3>Artiklid</h3>\n\n  <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Saksa artikkel ei ühti alati eesti keele soo mõistega. Seepärast on nimisõnu kõige parem õppida koos artikliga.</div>\n  </div>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Artiklite näited</h4>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Tisch — laud</div>\n      <div class=\"kurss-example\">die Tür — uks</div>\n      <div class=\"kurss-example\">das Messer — nuga</div>\n      <div class=\"kurss-example\">das Mädchen — tüdruk</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♂</span>Sageli DER</h4>\n    <p class=\"artikuli-explain\">DER on sageli meessoost isikud, päevad, kuud, aastaajad ja mõned sõnad kindlate lõppudega.</p>\n\n    <h5 class=\"artikuli-subtitle\">Reeglid</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-er → sageli DER, näiteks: der Computer, der Lehrer <span class=\"artikuli-note\">aga mitte alati</span></div>\n      <div class=\"kurss-example\">-ling → sageli DER, näiteks: der Schmetterling</div>\n      <div class=\"kurss-example\">-ismus → sageli DER, näiteks: der Tourismus, der Kapitalismus</div>\n      <div class=\"kurss-example\">meessoost isikud → der Mann, der Vater</div>\n      <div class=\"kurss-example\">elukutsed → der Lehrer, der Arzt</div>\n      <div class=\"kurss-example\">autobrändid → der BMW, der Mercedes</div>\n      <div class=\"kurss-example\">päevad → der Montag, der Dienstag</div>\n      <div class=\"kurss-example\">kuud → der August, der Dezember</div>\n      <div class=\"kurss-example\">aastaajad → der Sommer, der Winter</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Näited</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Mann — mees</div>\n      <div class=\"kurss-example\">der Vater — isa</div>\n      <div class=\"kurss-example\">der Montag — esmaspäev</div>\n      <div class=\"kurss-example\">der August — august</div>\n      <div class=\"kurss-example\">der Sommer — suvi</div>\n      <div class=\"kurss-example\">der Lehrer — õpetaja</div>\n      <div class=\"kurss-example\">der Computer — arvuti</div>\n      <div class=\"kurss-example\">der Schmetterling — liblikas</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♀</span>Sageli DIE</h4>\n    <p class=\"artikuli-explain\">DIE on sageli naissoost isikud, mitmus ja sõnad lõppudega -ung, -heit, -keit, -schaft, -ion, -tät, -ei.</p>\n\n    <h5 class=\"artikuli-subtitle\">Reeglid</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-ung → die Wohnung, die Rechnung</div>\n      <div class=\"kurss-example\">-heit → die Freiheit, die Gesundheit</div>\n      <div class=\"kurss-example\">-keit → die Möglichkeit</div>\n      <div class=\"kurss-example\">-schaft → die Mannschaft</div>\n      <div class=\"kurss-example\">-ion → die Nation</div>\n      <div class=\"kurss-example\">-tät → die Universität</div>\n      <div class=\"kurss-example\">-ei → die Polizei, die Bäckerei</div>\n      <div class=\"kurss-example\">naissoost isikud → die Frau, die Mutter</div>\n      <div class=\"kurss-example\">mootorrattabrändid → die Harley-Davidson, die Yamaha</div>\n      <div class=\"kurss-example\">mitmus → die Autos, die Häuser</div>\n      <div class=\"kurss-example\">mitmus peaaegu alati → die Autos, die Häuser, die Kinder</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Näited</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Frau — naine</div>\n      <div class=\"kurss-example\">die Mutter — ema</div>\n      <div class=\"kurss-example\">die Wohnung — korter</div>\n      <div class=\"kurss-example\">die Rechnung — arve</div>\n      <div class=\"kurss-example\">die Freiheit — vabadus</div>\n      <div class=\"kurss-example\">die Möglichkeit — võimalus</div>\n      <div class=\"kurss-example\">die Mannschaft — meeskond</div>\n      <div class=\"kurss-example\">die Nation — rahvus</div>\n      <div class=\"kurss-example\">die Universität — ülikool</div>\n      <div class=\"kurss-example\">die Polizei — politsei</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>◇</span>Sageli DAS</h4>\n    <p class=\"artikuli-explain\">DAS on sageli deminutiivid lõppudega -chen / -lein, paljud sõnad lõppudega -ment / -um ja tegusõnad nimisõnadena.</p>\n\n    <h5 class=\"artikuli-subtitle\">Reeglid</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-chen → das Mädchen, das Häuschen</div>\n      <div class=\"kurss-example\">-lein → das Fräulein</div>\n      <div class=\"kurss-example\">-ment → das Instrument</div>\n      <div class=\"kurss-example\">-um → das Zentrum, das Museum</div>\n      <div class=\"kurss-example\">metallid → das Gold, das Silber, das Eisen</div>\n      <div class=\"kurss-example\">keemilised elemendid → das Eisen, das Sauerstoff</div>\n      <div class=\"kurss-example\">hotellid → das Hotel</div>\n      <div class=\"kurss-example\">värvid nimisõnadena → das Rot, das Blau</div>\n      <div class=\"kurss-example\">tegusõna nimisõnana → das Essen, das Lernen</div>\n      <div class=\"kurss-example\">tegusõnad nimisõnadena → das Essen, das Lernen, das Lesen</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Näited</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">das Kind — laps</div>\n      <div class=\"kurss-example\">das Mädchen — tüdruk</div>\n      <div class=\"kurss-example\">das Häuschen — majake</div>\n      <div class=\"kurss-example\">das Instrument — instrument</div>\n      <div class=\"kurss-example\">das Zentrum — keskus</div>\n      <div class=\"kurss-example\">das Museum — muuseum</div>\n      <div class=\"kurss-example\">das Essen — söömine / toit</div>\n      <div class=\"kurss-example\">das Lernen — õppimine</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>!</span>Olulised erandid / tuleb õppida koos artikliga</h4>\n    <p class=\"artikuli-explain\">Mõne sõna puhul ei saa artiklit kindlalt määrata lõpu või eesti keele soo järgi. Neid on kõige parem õppida koos artikliga.</p>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Tür — uks</div>\n      <div class=\"kurss-example\">das Messer — nuga</div>\n      <div class=\"kurss-example\">die Sonne — päike</div>\n      <div class=\"kurss-example\">der Mond — kuu</div>\n      <div class=\"kurss-example\">das Mädchen — tüdruk</div>\n      <div class=\"kurss-example\">das Auto — auto</div>\n      <div class=\"kurss-example\">der Käse — juust</div>\n      <div class=\"kurss-example\">die Gabel — kahvel</div>\n    </div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Lõpud ja sõnarühmad aitavad artiklit ära arvata, kuid need ei ole 100% kindel reegel. Kui sa ei ole kindel, õpi sõna koos artikliga.</div>\n  </div>\n",
  "kurssPronounsLesson": "\n  <h3>Asesõnad</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominatiiv, akusatiiv ja datiiv — asesõnade vormid.</div>\n  </div>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>N</span>Nominatiiv — kes/mis?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich — mina</div><div class=\"kurss-example\">du — sina</div><div class=\"kurss-example\">er — tema (mees)</div><div class=\"kurss-example\">sie — tema (naine)</div><div class=\"kurss-example\">es — see</div><div class=\"kurss-example\">wir — meie</div><div class=\"kurss-example\">ihr — teie</div><div class=\"kurss-example\">sie — nemad</div><div class=\"kurss-example\">Sie — Teie (viisakusvorm)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>A</span>Akusatiiv — keda/mida?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mich — mind</div><div class=\"kurss-example\">dich — sind</div><div class=\"kurss-example\">ihn — teda (m.)</div><div class=\"kurss-example\">sie — teda (n.)</div><div class=\"kurss-example\">es — seda</div><div class=\"kurss-example\">uns — meid</div><div class=\"kurss-example\">euch — teid</div><div class=\"kurss-example\">sie — neid</div><div class=\"kurss-example\">Sie — Teid (viisakusvorm)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>D</span>Datiiv — kellele?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mir — mulle</div><div class=\"kurss-example\">dir — sulle</div><div class=\"kurss-example\">ihm — temale (m.)</div><div class=\"kurss-example\">ihr — temale (n.)</div><div class=\"kurss-example\">uns — meile</div><div class=\"kurss-example\">euch — teile</div><div class=\"kurss-example\">ihnen — neile</div><div class=\"kurss-example\">Ihnen — Teile (viisakusvorm)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>?</span>Kuidas valida vormi?</h4>\n    <ul class=\"kurss-summary-list\"><li><span class=\"case-blue\">Nominatiiv</span> — lause alus (kes teeb?)</li><li><span class=\"case-red\">Akusatiiv</span> — otsene sihitis (keda/mida?)</li><li><span class=\"case-green\">Datiiv</span> — kaudne sihitis (kellele?)</li></ul>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Näited</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">dich</span>. — Ma näen sind.</div><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">ihn</span>. — Ma näen teda.</div><div class=\"kurss-example\">Wir mögen <span class=\"case-red\">euch</span>. — Meile meeldite teie.</div><div class=\"kurss-example\">Ich helfe <span class=\"case-green\">dir</span>. — Ma aitan sind.</div><div class=\"kurss-example\">Ich gebe <span class=\"case-green\">ihm</span> ein Buch. — Ma annan talle raamatu.</div><div class=\"kurss-example\">Wir danken <span class=\"case-green\">euch</span>. — Me täname teid.</div></div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominatiiv on alati lause alus, aga akusatiiv ja datiiv on sihitised. Vaata tegusõna ja küsi: <span class=\"case-red\">keda/mida?</span> või <span class=\"case-green\">kellele?</span></div>\n  </div>\n",
  "kurssPronunciationLesson": "\n            <h3>Täishäälikud — pikk ja lühike</h3>\n            <p class=\"kurss-lesson-intro\">Saksa keeles võivad täishäälikud olla pikad või lühikesed. See mõjutab sõna hääldust.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Pikk täishäälik</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">warm (varm) — soe</div><div class=\"kurss-example\">gut (guut) — hea</div><div class=\"kurss-example\">Tat (taat) — tegu / tegevus</div><div class=\"kurss-example\">Flur (fluur) — koridor</div><div class=\"kurss-example\">Weg (veek) — tee</div><div class=\"kurss-example\">Hut (huut) — kübar</div><div class=\"kurss-example\">Hof (hoof) — õu</div><div class=\"kurss-example\">Schlaf (šlaaf) — uni</div></div>\n              <p>Kui täishäälikule järgneb üks kaashäälik, hääldatakse täishäälikut sageli pikalt.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Lühike täishäälik</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Pilz (pilts) — seen</div><div class=\"kurss-example\">Wort (vort) — sõna</div><div class=\"kurss-example\">Mund (munt) — suu</div><div class=\"kurss-example\">bald (balt) — varsti</div><div class=\"kurss-example\">scharf (šarf) — terav</div><div class=\"kurss-example\">Feld (felt) — põld</div><div class=\"kurss-example\">voll (fol) — täis</div></div>\n              <p>Kui täishäälikule järgneb kaks või rohkem kaashäälikut, hääldatakse täishäälikut sageli lühidalt.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Lõpud en / el / er</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">singen (zingen) — laulma</div><div class=\"kurss-example\">tragen (traagen) — kandma</div><div class=\"kurss-example\">Garten (garten) — aed</div><div class=\"kurss-example\">Vogel (fogel) — lind</div><div class=\"kurss-example\">Segel (zeegel) — puri</div><div class=\"kurss-example\">Braten (braaten) — praad</div><div class=\"kurss-example\">Bogen (boogen) — kaar</div><div class=\"kurss-example\">Spiegel (špiigel) — peegel</div><div class=\"kurss-example\">Finger (finger) — sõrm</div><div class=\"kurss-example\">Halter (halter) — hoidik</div><div class=\"kurss-example\">Arbeiter (arbaiter) — töömees</div><div class=\"kurss-example\">Häuser (hoizer) — majad</div><div class=\"kurss-example\">wieder (viider) — jälle</div><div class=\"kurss-example\">breiter (braiter) — laiem</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Täht h pikendusmärgina</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Rahmen (raamen) — raam</div><div class=\"kurss-example\">Ohr (oor) — kõrv</div><div class=\"kurss-example\">Kohle (koole) — süsi</div><div class=\"kurss-example\">Zahl (tsaal) — arv</div><div class=\"kurss-example\">ihn (iin) — teda</div><div class=\"kurss-example\">ihm (iim) — talle</div><div class=\"kurss-example\">Huhn (huun) — kana</div><div class=\"kurss-example\">nahm (naam) — võttis</div><div class=\"kurss-example\">nehmen (neemen) — võtma</div><div class=\"kurss-example\">Schuh (šuu) — king</div></div>\n              <p>Mõnes sõnas pikendab h eelnevat täishäälikut. Sellistel juhtudel h-d tavaliselt ei hääldata.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Lõpud e-ga</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Lampe (lampe) — lamp</div><div class=\"kurss-example\">Hase (haaze) — jänes</div><div class=\"kurss-example\">Knabe (knaabe) — poiss</div><div class=\"kurss-example\">Rabe (raabe) — kaaren</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Pikk i = ie</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">die (dii) — artikkel “die”</div><div class=\"kurss-example\">diese (diize) — see / need</div><div class=\"kurss-example\">wieder (viider) — jälle</div><div class=\"kurss-example\">Fliege (fliige) — kärbes</div><div class=\"kurss-example\">Ziege (tsiige) — kits</div><div class=\"kurss-example\">Stiel (štiil) — vars</div><div class=\"kurss-example\">Dieb (diip) — varas</div><div class=\"kurss-example\">hier (hiir) — siin</div></div>\n              <p>Pikk i kirjutatakse saksa keeles sageli kui ie.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Kahekordsed täishäälikud</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Saal (zaal) — saal</div><div class=\"kurss-example\">Saat (zaat) — külv</div><div class=\"kurss-example\">Staat (štaat) — riik</div><div class=\"kurss-example\">Beere (beere) — mari</div><div class=\"kurss-example\">See (zee) — järv / meri</div><div class=\"kurss-example\">Beet (beet) — peenar</div><div class=\"kurss-example\">Boot (boot) — paat</div><div class=\"kurss-example\">Moor (moor) — soo</div><div class=\"kurss-example\">Moos (moos) — sammal</div></div>\n              <p>Kahekordseid täishäälikuid hääldatakse tavaliselt pikalt.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ä</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Wand (vant) — sein</div><div class=\"kurss-example\">Wände (vende) — seinad</div><div class=\"kurss-example\">Vater (faater) — isa</div><div class=\"kurss-example\">Väter (feeter) — isad</div><div class=\"kurss-example\">Schrank (šrank) — kapp</div><div class=\"kurss-example\">Schränke (šrenke) — kapid</div><div class=\"kurss-example\">Bank (bank) — pink / pank</div><div class=\"kurss-example\">Bänke (benke) — pingid</div><div class=\"kurss-example\">Tal (taal) — org</div><div class=\"kurss-example\">Täler (teeler) — orud</div></div>\n              <p>ä on a-tähe muundvorm (Umlaut).</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ö</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Rose (rooze) — roos</div><div class=\"kurss-example\">Röschen (reešen) — roosike</div><div class=\"kurss-example\">Ofen (oofen) — ahi</div><div class=\"kurss-example\">Öfen (eefen) — ahjud</div><div class=\"kurss-example\">Rock (rok) — seelik</div><div class=\"kurss-example\">Röcke (röke) — seelikud</div></div>\n              <p>ö on o-tähe muundvorm (Umlaut).</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ü</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">kurz (kurts) — lühike</div><div class=\"kurss-example\">kürzer (kürtser) — lühem</div><div class=\"kurss-example\">Kunst (kunst) — kunst</div><div class=\"kurss-example\">Künste (künste) — kunstid</div><div class=\"kurss-example\">Mutter (muter) — ema</div><div class=\"kurss-example\">Mütter (mütter) — emad</div></div>\n              <p>ü on u-tähe muundvorm (Umlaut).</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Diftong: äu</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Baum (baum) — puu</div><div class=\"kurss-example\">Bäume (boime) — puud</div><div class=\"kurss-example\">Haus (haus) — maja</div><div class=\"kurss-example\">Häuser (hoizer) — majad</div><div class=\"kurss-example\">Strauch (štrauh) — põõsas</div><div class=\"kurss-example\">Sträucher (štroiher) — põõsad</div><div class=\"kurss-example\">Maus (maus) — hiir</div><div class=\"kurss-example\">Mäuse (moize) — hiired</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Diftong: eu</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">heute (hoite) — täna</div><div class=\"kurss-example\">Leute (loite) — inimesed</div><div class=\"kurss-example\">neu (noi) — uus</div><div class=\"kurss-example\">neun (noin) — üheksa</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Diftong: ei</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">mein (main) — minu</div><div class=\"kurss-example\">dein (dain) — sinu</div><div class=\"kurss-example\">sein (zain) — tema oma / olema</div><div class=\"kurss-example\">frei (frai) — vaba</div><div class=\"kurss-example\">arbeiten (arbaiten) — töötama</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>2. õppetunni hääldusmärkused</h4>\n              <ul class=\"kurss-summary-list\"><li>sõnades ich, nicht, rechnen, zeichnen hääldatakse “ch” pehmelt</li><li>sõnades arbeiten ja zeichnen hääldatakse “ei” kui “ai”</li><li>“sp” sõna alguses hääldatakse kui “šp”</li><li>tegusõnas tun hääldatakse täht “u” pikalt</li></ul>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Kokkuvõte</h4>\n              <ul class=\"kurss-summary-list\"><li>üks kaashäälik pärast täishäälikut → sageli pikk täishäälik</li><li>kaks või rohkem kaashäälikut → sageli lühike täishäälik</li><li>h võib täishäälikut pikendada</li><li>ie tähendab sageli pikka i-d</li><li>kahekordsed täishäälikud on tavaliselt pikad</li></ul>\n            </section>\n",
  "kurssConsonantsLesson": "\n            <h3>Kaashäälikud ja tähekombinatsioonid</h3>\n            <p class=\"kurss-lesson-intro\">Saksa keeles hääldatakse mõningaid kaashäälikuid ja tähekombinatsioone teisiti, kui neid kirjutatakse. Selles õppetunnis on algajale kõige olulisemad näited.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Kaashäälikud</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">das Rad (raat) — ratas</div><div class=\"kurss-example\">die Räder (reeder) — rattad</div><div class=\"kurss-example\">Bad (baat) — vann</div><div class=\"kurss-example\">Bäder (beeder) — vannid</div></div>\n              <p>Sõna lõpus ei hääldata kaashäälikuid sageli samamoodi, nagu neid kirjutatakse.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ch</h4>\n              <p>“ch” võib hääldada pehmelt või kõvalt. Mõnes sõnas kõlab see nagu “h”, teistes lähemale “k”-le.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">rechnen (rehnen) — arvutama</div><div class=\"kurss-example\">zeichnen (tsaihnen) — joonistama</div><div class=\"kurss-example\">nicht (niht) — mitte</div><div class=\"kurss-example\">schlecht (šleht) — halb</div><div class=\"kurss-example\">mich (mih) — mind</div><div class=\"kurss-example\">dich (dih) — sind</div><div class=\"kurss-example\">Strauch (štrauh) — põõsas</div><div class=\"kurss-example\">noch (noh) — veel</div><div class=\"kurss-example\">Nacht (naht) — öö</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>sch</h4>\n              <p>“sch” hääldatakse saksa keeles nagu eesti “š”.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Schule (šuule) — kool</div><div class=\"kurss-example\">Schüler (šüler) — õpilane</div><div class=\"kurss-example\">Schiff (šif) — laev</div><div class=\"kurss-example\">Schraube (šraube) — kruvi</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>sp ja st sõna alguses</h4>\n              <p>Sõna või silbi alguses hääldatakse “sp” sageli kui “šp”, aga “st” kui “št”.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">spielen (špiilen) — mängima</div><div class=\"kurss-example\">Sprung (šprung) — hüpe</div><div class=\"kurss-example\">stehen (šteen) — seisma</div><div class=\"kurss-example\">Stall (štal) — laut</div><div class=\"kurss-example\">Stand (štant) — seisund / koht</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>qu</h4>\n              <p>“qu” hääldatakse saksa keeles tavaliselt kui “kv”.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Qual (kvaal) — piin</div><div class=\"kurss-example\">Quartier (kvartiir) — kvartal / peatuskoht</div><div class=\"kurss-example\">quer (kveer) — risti</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>s ja z</h4>\n              <p>Sõna alguses kõlab “s” sageli kui “z”. Täht “z” kõlab saksa keeles nagu eesti “ts”.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">sagen (zaagen) — ütlema</div><div class=\"kurss-example\">singen (zingen) — laulma</div><div class=\"kurss-example\">Rose (rooze) — roos</div><div class=\"kurss-example\">Zahl (tsaal) — arv</div><div class=\"kurss-example\">Zeit (tsait) — aeg</div><div class=\"kurss-example\">Zink (tsink) — tsink</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>v</h4>\n              <p>Saksa keeles hääldatakse “v” sageli kui “f”. Võõrsõnades kõlab see sageli nagu eesti “v”.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Vater (faater) — isa</div><div class=\"kurss-example\">von (fon) — millest</div><div class=\"kurss-example\">viel (fiil) — palju</div><div class=\"kurss-example\">vier (fiir) — neli</div><div class=\"kurss-example\">Villa (villa) — villa</div><div class=\"kurss-example\">Klavier (klaviir) — klaver</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>x ja y</h4>\n              <p>“x” hääldatakse kui “ks”. “y” hääldatakse mõnes sõnas kui “ü”.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Felix (feeliks) — Felix</div><div class=\"kurss-example\">Axt (akst) — kirves</div><div class=\"kurss-example\">Mystik (müstik) — müstika</div><div class=\"kurss-example\">Nyx (nüks) — Nyx</div><div class=\"kurss-example\">Mythe (müte) — müüt</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ß</h4>\n              <p>“ß” hääldatakse saksa keeles kui “s”.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Fuß (fuus) — jalatald</div><div class=\"kurss-example\">Füße (füse) — jalatallad</div><div class=\"kurss-example\">Grüße (grüse) — tervitused</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Kokkuvõte</h4>\n              <ul class=\"kurss-summary-list\"><li>sch → š</li><li>sp / st alguses → šp / št</li><li>qu → kv</li><li>z → ts</li><li>v sageli → f</li><li>x → ks</li><li>ß → s</li></ul>\n            </section>\n",
  "kurssVerbBasicsLesson": "\n            <h3>Tegusõnade alused</h3>\n            <p class=\"kurss-lesson-intro\">1. õppetunni tegusõnad ja pöörded.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Tegusõnad</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">kommen — tulema</div><div class=\"kurss-example\">gehen — minema</div><div class=\"kurss-example\">stehen — seisma</div><div class=\"kurss-example\">singen — laulma</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>kommen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich komme — mina tulen</div><div class=\"kurss-example\">du kommst — sina tuled</div><div class=\"kurss-example\">er kommt — tema tuleb (mees)</div><div class=\"kurss-example\">sie kommt — tema tuleb (naine)</div><div class=\"kurss-example\">wir kommen — meie tuleme</div><div class=\"kurss-example\">ihr kommt — teie tulete</div><div class=\"kurss-example\">sie kommen — nemad tulevad</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>gehen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich gehe — mina lähen</div><div class=\"kurss-example\">du gehst — sina lähed</div><div class=\"kurss-example\">er geht — tema läheb (mees)</div><div class=\"kurss-example\">sie geht — tema läheb (naine)</div><div class=\"kurss-example\">wir gehen — meie läheme</div><div class=\"kurss-example\">ihr geht — teie lähete</div><div class=\"kurss-example\">sie gehen — nemad lähevad</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>stehen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich stehe — mina seisan</div><div class=\"kurss-example\">du stehst — sina seisad</div><div class=\"kurss-example\">er steht — tema seisab (mees)</div><div class=\"kurss-example\">sie steht — tema seisab (naine)</div><div class=\"kurss-example\">wir stehen — meie seisame</div><div class=\"kurss-example\">ihr steht — teie seisate</div><div class=\"kurss-example\">sie stehen — nemad seisavad</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>singen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich singe — mina laulan</div><div class=\"kurss-example\">du singst — sina laulad</div><div class=\"kurss-example\">er singt — tema laulab (mees)</div><div class=\"kurss-example\">sie singt — tema laulab (naine)</div><div class=\"kurss-example\">wir singen — meie laulame</div><div class=\"kurss-example\">ihr singt — teie laulate</div><div class=\"kurss-example\">sie singen — nemad laulavad</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>2. õppetunni tegusõnad</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">spielen — mängima</div><div class=\"kurss-example\">arbeiten — töötama</div><div class=\"kurss-example\">fragen — küsima</div><div class=\"kurss-example\">antworten — vastama</div><div class=\"kurss-example\">rechnen — arvutama</div><div class=\"kurss-example\">zeichnen — joonistama</div><div class=\"kurss-example\">tun — tegema</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>spielen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich spiele — mina mängin</div><div class=\"kurss-example\">du spielst — sina mängid</div><div class=\"kurss-example\">er spielt — tema mängib (mees)</div><div class=\"kurss-example\">sie spielt — tema mängib (naine)</div><div class=\"kurss-example\">wir spielen — meie mängime</div><div class=\"kurss-example\">ihr spielt — teie mängite</div><div class=\"kurss-example\">sie spielen — nemad mängivad</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>arbeiten</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich arbeite — mina töötan</div><div class=\"kurss-example\">du arbeitest — sina töötad</div><div class=\"kurss-example\">er arbeitet — tema töötab (mees)</div><div class=\"kurss-example\">sie arbeitet — tema töötab (naine)</div><div class=\"kurss-example\">wir arbeiten — meie töötame</div><div class=\"kurss-example\">ihr arbeitet — teie töötate</div><div class=\"kurss-example\">sie arbeiten — nemad töötavad</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>fragen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich frage — mina küsin</div><div class=\"kurss-example\">du fragst — sina küsid</div><div class=\"kurss-example\">er fragt — tema küsib (mees)</div><div class=\"kurss-example\">sie fragt — tema küsib (naine)</div><div class=\"kurss-example\">wir fragen — meie küsime</div><div class=\"kurss-example\">ihr fragt — teie küsite</div><div class=\"kurss-example\">sie fragen — nemad küsivad</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>antworten</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich antworte — mina vastan</div><div class=\"kurss-example\">du antwortest — sina vastad</div><div class=\"kurss-example\">er antwortet — tema vastab (mees)</div><div class=\"kurss-example\">sie antwortet — tema vastab (naine)</div><div class=\"kurss-example\">wir antworten — meie vastame</div><div class=\"kurss-example\">ihr antwortet — teie vastate</div><div class=\"kurss-example\">sie antworten — nemad vastavad</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>rechnen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich rechne — mina arvutan</div><div class=\"kurss-example\">du rechnest — sina arvutad</div><div class=\"kurss-example\">er rechnet — tema arvutab (mees)</div><div class=\"kurss-example\">sie rechnet — tema arvutab (naine)</div><div class=\"kurss-example\">wir rechnen — meie arvutame</div><div class=\"kurss-example\">ihr rechnet — teie arvutate</div><div class=\"kurss-example\">sie rechnen — nemad arvutavad</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>zeichnen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich zeichne — mina joonistan</div><div class=\"kurss-example\">du zeichnest — sina joonistad</div><div class=\"kurss-example\">er zeichnet — tema joonistab (mees)</div><div class=\"kurss-example\">sie zeichnet — tema joonistab (naine)</div><div class=\"kurss-example\">wir zeichnen — meie joonistame</div><div class=\"kurss-example\">ihr zeichnet — teie joonistate</div><div class=\"kurss-example\">sie zeichnen — nemad joonistavad</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>tun</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich tue — mina teen</div><div class=\"kurss-example\">du tust — sina teed</div><div class=\"kurss-example\">er tut — tema teeb (mees)</div><div class=\"kurss-example\">sie tut — tema teeb (naine)</div><div class=\"kurss-example\">wir tun — meie teeme</div><div class=\"kurss-example\">ihr tut — teie teete</div><div class=\"kurss-example\">sie tun — nemad teevad</div></div>\n            </section>\n",
  "kurssSentenceStructureLesson": "\n            <h3>Lause ehitus</h3>\n            <p class=\"kurss-lesson-intro\">Küsilauses seisab tegusõna saksa keeles tavaliselt esimesel kohal.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Näited</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Du kommst. — Sina tuled.</div><div class=\"kurss-example\">Kommst du? — Kas sina tuled?</div><div class=\"kurss-example\">Er singt. — Tema laulab.</div><div class=\"kurss-example\">Singt er? — Kas tema laulab?</div><div class=\"kurss-example\">Stehst du? — Kas sina seisad?</div><div class=\"kurss-example\">Ja, ich stehe. — Jah, mina seisan.</div><div class=\"kurss-example\">Geht ihr? — Kas teie lähete?</div><div class=\"kurss-example\">Ja, wir gehen. — Jah, meie läheme.</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>Küsimused sõnaga „was”</h4>\n              <p>Kui küsimus algab küsisõnaga, seisab tegusõna saksa keeles tavaliselt kohe küsisõna järel.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Was tust du? — Mida sina teed?</div><div class=\"kurss-example\">Was tut er? — Mida tema teeb (mees)?</div><div class=\"kurss-example\">Was tut sie? — Mida tema teeb (naine)?</div><div class=\"kurss-example\">Was tun sie? — Mida nemad teevad?</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Eitus sõnaga „nicht”</h4>\n              <p>Kui eitus „nicht” käib tegusõna kohta, seisab see saksa keeles tavaliselt tegusõna järel.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Ich spiele nicht. — Mina ei mängi.</div><div class=\"kurss-example\">Paul fragt nicht. — Paul ei küsi.</div><div class=\"kurss-example\">Er kommt nicht. — Tema ei tule.</div><div class=\"kurss-example\">Sie singen nicht. — Nemad ei laula.</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Laused 2. õppetunnist</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Spielst du? — Kas sina mängid?</div><div class=\"kurss-example\">Nein, ich spiele nicht, ich arbeite. — Ei, mina ei mängi, mina töötan.</div><div class=\"kurss-example\">Paul fragt nicht, er arbeitet. — Paul ei küsi, tema töötab.</div><div class=\"kurss-example\">Arbeitest du? — Kas sina töötad?</div><div class=\"kurss-example\">Nein, ich arbeite nicht, ich singe. — Ei, mina ei tööta, mina laulan.</div><div class=\"kurss-example\">Was tut Paul? — Mida teeb Paul?</div><div class=\"kurss-example\">Er spielt. — Tema mängib.</div><div class=\"kurss-example\">Was tut Marie? — Mida teeb Marie?</div><div class=\"kurss-example\">Sie singt. — Tema laulab.</div><div class=\"kurss-example\">Paul spielt, aber Marie singt. — Paul mängib, aga Marie laulab.</div><div class=\"kurss-example\">Singt ihr? — Kas teie laulate?</div><div class=\"kurss-example\">Nein, wir singen nicht, wir arbeiten. — Ei, meie ei laula, meie töötame.</div><div class=\"kurss-example\">Was tun Paul und Marie? — Mida teevad Paul ja Marie?</div><div class=\"kurss-example\">Sie fragen. — Nemad küsivad.</div><div class=\"kurss-example\">Sie antworten nicht. — Nemad ei vasta.</div><div class=\"kurss-example\">Wer arbeitet? — Kes töötab?</div><div class=\"kurss-example\">Wir arbeiten. — Meie töötame.</div><div class=\"kurss-example\">Wir rechnen und zeichnen. — Meie arvutame ja joonistame.</div><div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen. — Nemad tulevad, küsivad, vastavad, töötavad, mängivad, laulavad ja lähevad.</div></div>\n            </section>\n",
  "kurssLesson1": "            <h3>1. õppetund</h3>\n            <p class=\"kurss-lesson-intro\">Esimene õppetund: tegusõnad olevikus, sõnad, hääldus, grammatika ja tõlkimine.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Tegusõnad olevikus</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info\">Tegusõnad ja nende pöörded olevikus.</div>\n                <div class=\"lesson1-verb-cards\">\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>kommen — tulema</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>komme</strong><span>mina tulen</span><span>du</span><strong>kommst</strong><span>sina tuled</span><span>er / sie</span><strong>kommt</strong><span>tema tuleb</span><span>wir</span><strong>kommen</strong><span>meie tuleme</span><span>ihr</span><strong>kommt</strong><span>teie tulete</span><span>sie / Sie</span><strong>kommen</strong><span>nemad / Teie tulevad</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>gehen — minema</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>gehe</strong><span>mina lähen</span><span>du</span><strong>gehst</strong><span>sina lähed</span><span>er / sie</span><strong>geht</strong><span>tema läheb</span><span>wir</span><strong>gehen</strong><span>meie läheme</span><span>ihr</span><strong>geht</strong><span>teie lähete</span><span>sie / Sie</span><strong>gehen</strong><span>nemad / Teie lähevad</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>stehen — seisma</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>stehe</strong><span>mina seisan</span><span>du</span><strong>stehst</strong><span>sina seisad</span><span>er / sie</span><strong>steht</strong><span>tema seisab</span><span>wir</span><strong>stehen</strong><span>meie seisame</span><span>ihr</span><strong>steht</strong><span>teie seisate</span><span>sie / Sie</span><strong>stehen</strong><span>nemad / Teie seisavad</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>singen — laulma</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>singe</strong><span>mina laulan</span><span>du</span><strong>singst</strong><span>sina laulad</span><span>er / sie</span><strong>singt</strong><span>tema laulab</span><span>wir</span><strong>singen</strong><span>meie laulame</span><span>ihr</span><strong>singt</strong><span>teie laulate</span><span>sie / Sie</span><strong>singen</strong><span>nemad / Teie laulavad</span></div>\n                  </article>\n                </div>\n                <section class=\"lesson1-block\">\n                  <h4>Näited</h4>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Stehst du?<br>Ja, ich stehe.</div><div class=\"kurss-example\">Steht Albert?<br>Ja, er steht.</div><div class=\"kurss-example\">Steht Marta?<br>Ja, sie steht.</div><div class=\"kurss-example\">Wer kommt und singt?<br>Albert und Marta kommen und singen.</div><div class=\"kurss-example\">Geht ihr?<br>Ja, wir gehen.</div><div class=\"kurss-example\">Wer steht und singt?<br>Albert und Marta stehen und singen.</div></div>\n                </section>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Sõnad</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info lesson1-vardini-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>Sõnade ligikaudne hääldus on antud sulgudes eesti tähtedega.<br>Seda tuleb järgida ka järgnevates õppetundides.</span></div>\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wir (vīr) — meie</div><div class=\"kurss-example\">Sõnas „wir“ hääldatakse i-d pikalt.</div><div class=\"kurss-example\">kommen (komen) — tulema</div><div class=\"kurss-example\">gehen (gē-en) — minema</div><div class=\"kurss-example\">stehen (štē-en) — seisma</div><div class=\"kurss-example\">singen (zingen) — laulma</div><div class=\"kurss-example\">du (dū) kommst — sina tuled</div><div class=\"kurss-example\">er (ēr) kommt — tema tuleb</div><div class=\"kurss-example\">sie (zī) kommt — tema tuleb (naine)</div><div class=\"kurss-example\">wer (vēr) — kes?</div><div class=\"kurss-example\">ja (jā) — jah</div></div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Hääldus</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Sõnade õige hääldus, mis on märgitud eesti tähtedega, on õppetundides ära toodud.</div><div class=\"kurss-example\">Wir (vīr) — meie. Sõnas wir hääldatakse ii alati pikalt.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatika</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>∞</span>Infinitiiv</h4><div class=\"lesson1-grammar-note\">Tegusõna algvorm. Tavaliselt lõpeb infinitiiv lõpuga -en.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">kommen</div><div class=\"kurss-example\">gehen</div><div class=\"kurss-example\">stehen</div><div class=\"kurss-example\">singen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♟</span>Oleviku lõpud</h4><div class=\"lesson1-ending-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><div class=\"lesson1-ending-info-body\"><p><strong>Eemalda tegusõna algvormist <span class=\"lesson1-ending-accent\">-en</span> ja lisa lõpp.</strong></p><p>Näide: kommen → komm + lõpp</p><div class=\"lesson1-ending-process\" aria-label=\"Oleviku lõppude moodustamise protsess\"><div class=\"lesson1-ending-step\"><strong>kommen</strong><span>algvorm</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>eemalda <span class=\"lesson1-ending-accent\">-en</span></strong><span>jääb tüvi</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>komm</strong><span>tüvi</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>lisa lõpp</strong><span>e / st / t</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-results\"><div>komm + <span class=\"lesson1-ending-accent\">e</span> = <strong>komme</strong></div><div>komm + <span class=\"lesson1-ending-accent\">st</span> = <strong>kommst</strong></div><div>komm + <span class=\"lesson1-ending-accent\">t</span> = <strong>kommt</strong></div></div></div></div></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich → -e</div><div class=\"kurss-example\">du → -st</div><div class=\"kurss-example\">er / sie → -t</div><div class=\"kurss-example\">wir → -en</div><div class=\"kurss-example\">ihr → -t</div><div class=\"kurss-example\">sie → -en</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>●</span>Näited</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich komme</div><div class=\"kurss-example\">du kommst</div><div class=\"kurss-example\">er kommt</div><div class=\"kurss-example\">wir kommen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>?</span>Küsilaused</h4><div class=\"lesson1-grammar-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>Saksa küsilauses liigub tegusõna tavaliselt esimesele kohale.</span></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Eesti keeles:<br>Sa tuled.<br>Kas sa tuled?</div><div class=\"kurss-example\">Vācu valodā:<br>Du kommst.<br>Kommst du?</div><div class=\"kurss-example\">du kommst — sina tuled<br>kommst du? — kas sina tuled?</div><div class=\"kurss-example\">er singt — tema laulab<br>singt er? — kas tema laulab?</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♣</span>Isikute erinevus</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er kommt — tema tuleb (mees)</div><div class=\"kurss-example\">sie kommt — tema tuleb (naine)</div><div class=\"kurss-example\">sie kommen — nemad tulevad</div></div></section>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Tõlgi</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson1-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"1. õppetunni harjutuskaart\">\n                    <span class=\"lesson1-training-progress\">1. õppetund · Tõlgi: 1 / 11</span>\n                    <span class=\"lesson1-training-text\">Kas sina tuled?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Klõpsa kaardil, et näha saksakeelset tõlget. Pärast vastust näitab järgmine klõps uut kaarti.</p>\n                </div>\n              </div>\n            </details>\n",
  "kurssLesson2": "            <h3>2. õppetund</h3>\n            <p class=\"kurss-lesson-intro\">Teine õppetund: dialoogid, sõnad, hääldus, grammatika ja tõlkimine.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialoogid / laused</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">Spielst du?<br>Nein, ich spiele nicht, ich arbeite.</div>\n                  <div class=\"kurss-example\">Paul fragt nicht, er arbeitet.</div>\n                  <div class=\"kurss-example\">Arbeitest du?<br>Nein, ich arbeite nicht, ich singe.</div>\n                  <div class=\"kurss-example\">Was tut Paul?<br>Er spielt.</div>\n                  <div class=\"kurss-example\">Was tut Marie?<br>Sie singt.</div>\n                  <div class=\"kurss-example\">Paul spielt, aber Marie singt.</div>\n                  <div class=\"kurss-example\">Singt ihr?<br>Nein, wir singen nicht, wir arbeiten.</div>\n                  <div class=\"kurss-example\">Was tun Paul und Marie?<br>Sie fragen.<br>Sie antworten nicht.</div>\n                  <div class=\"kurss-example\">Wer arbeitet?<br>Wir arbeiten.<br>Wir rechnen und zeichnen.</div>\n                  <div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen.</div>\n                </div>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Sõnad</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">spielen — mängima</div>\n                  <div class=\"kurss-example\">nein — ei</div>\n                  <div class=\"kurss-example\">nicht — mitte</div>\n                  <div class=\"kurss-example\">arbeiten — töötama</div>\n                  <div class=\"kurss-example\">fragen — küsima</div>\n                  <div class=\"kurss-example\">was tut er? — mida tema teeb?</div>\n                  <div class=\"kurss-example\">was tun sie? — mida nemad teevad?</div>\n                  <div class=\"kurss-example\">aber — aga</div>\n                  <div class=\"kurss-example\">antworten — vastama</div>\n                  <div class=\"kurss-example\">rechnen — arvutama</div>\n                  <div class=\"kurss-example\">zeichnen — joonistama</div>\n                  <div class=\"kurss-example\">Marie — Marie</div>\n                </div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Hääldus</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Sõnades ich, nicht, rechnen ja zeichnen hääldatakse häälikut ch pehmelt, umbes nagu eesti sõnades „tehnika“ ja „Friedrich“.</div><div class=\"kurss-example\">Sõnades arbeiten ja zeichnen hääldatakse diftongi ei nagu ai.</div><div class=\"kurss-example\">Līdzskaņu kopojumu sp izrunā kā šp: spielen (špīlen).</div><div class=\"kurss-example\">Darbības vārdā tun u izrunājams gari visās personās.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatika</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>1</span>Lõpud e-ga</h4>\n                  <div class=\"lesson1-grammar-note\">Kui tegusõna tüvi lõpeb tähtedega t, d, chn, siis lõppude -st ja -t ees seisab pöördel e.</div>\n                  <h5 class=\"lesson2-subtitle\">arbeiten</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich arbeite</div><div class=\"kurss-example\">du arbeitest</div><div class=\"kurss-example\">er arbeitet</div><div class=\"kurss-example\">sie arbeitet</div><div class=\"kurss-example\">wir arbeiten</div><div class=\"kurss-example\">ihr arbeitet</div><div class=\"kurss-example\">sie arbeiten</div></div>\n                  <h5 class=\"lesson2-subtitle\">rechnen</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich rechne</div><div class=\"kurss-example\">du rechnest</div><div class=\"kurss-example\">er rechnet</div><div class=\"kurss-example\">sie rechnet</div><div class=\"kurss-example\">wir rechnen</div><div class=\"kurss-example\">ihr rechnet</div><div class=\"kurss-example\">sie rechnen</div></div>\n                  <h5 class=\"lesson2-subtitle\">tun</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich tue</div><div class=\"kurss-example\">du tust</div><div class=\"kurss-example\">er tut</div><div class=\"kurss-example\">sie tut</div><div class=\"kurss-example\">wir tun</div><div class=\"kurss-example\">ihr tut</div><div class=\"kurss-example\">sie tun</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>2</span>Küsisõna</h4>\n                  <div class=\"lesson1-grammar-note\">Küsilausetes, mis algavad küsisõnaga, näiteks: mida? kes? milline? miks? mispärast? jne, seisab tegusõna kohe küsisõna järel.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Was tust du? — Mida sina teed?</div><div class=\"kurss-example\">Was tut er? — Mida tema teeb (mees)?</div><div class=\"kurss-example\">Was tut sie? — Mida tema teeb (naine)?</div><div class=\"kurss-example\">Was tun sie? — Mida nemad teevad?</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>3</span>Eitus sõnaga nicht</h4>\n                  <div class=\"lesson1-grammar-note\">Kui eitus nicht käib tegusõna kohta, siis seisab eitav sõna tegusõna järel.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Er kommt nicht. — Tema ei tule.</div><div class=\"kurss-example\">Sie singen nicht. — Nemad ei laula.</div></div>\n                </section>\n              </div>\n            </details>\n                                    <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Tõlgi</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson2-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"2. õppetunni tõlkekaart\">\n                    <span class=\"lesson1-training-progress\">2. õppetund · Tõlgi: 1 / 15</span>\n                    <span class=\"lesson1-training-text\">Kes küsib?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Klõpsa kaardil, et näha saksakeelset tõlget. Pärast vastust näitab järgmine klõps uut kaarti.</p>\n                </div>\n              </div>\n            </details>\n",
  "kurssLesson3": "            <h3>3. õppetund</h3>\n            <p class=\"kurss-lesson-intro\">Kolmas õppetund: dialoogid, sõnad, hääldus, grammatika ja tõlkimine.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialoogid / laused</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wer rechnet und zeichnet?<br>Wir rechnen und zeichnen.</div><div class=\"kurss-example\">Wer kommt?<br>Paul und Anna kommen.</div><div class=\"kurss-example\">Was steht hier?<br>Hier steht ein Tisch.</div><div class=\"kurss-example\">Was steht dort?<br>Dort steht eine Bank.</div><div class=\"kurss-example\">Was liegt hier?<br>Hier liegt ein Buch.</div><div class=\"kurss-example\">Was liegt dort?<br>Dort liegt ein Heft.</div><div class=\"kurss-example\">Was hängt hier?<br>Hier hängt ein Bild.</div><div class=\"kurss-example\">Was hängt dort?<br>Dort hängt eine Tafel.</div><div class=\"kurss-example\">Wie ist das Buch?<br>Das Buch ist dick.</div><div class=\"kurss-example\">Wie ist das Heft?<br>Das Heft ist dünn.</div><div class=\"kurss-example\">Wie ist die Bank?<br>Die Bank ist niedrig.</div><div class=\"kurss-example\">Wie ist der Tisch?<br>Der Tisch ist hoch.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Sõnad</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wer — kes</div><div class=\"kurss-example\">was — mis</div><div class=\"kurss-example\">hier — siin</div><div class=\"kurss-example\">dort — seal</div><div class=\"kurss-example\">der Tisch — laud</div><div class=\"kurss-example\">ein Tisch — laud</div><div class=\"kurss-example\">die Bank — pink</div><div class=\"kurss-example\">eine Bank — pink</div><div class=\"kurss-example\">liegen — lamama</div><div class=\"kurss-example\">liegt hier ein Buch? — kas siin on raamat?</div><div class=\"kurss-example\">das Buch — raamat</div><div class=\"kurss-example\">ein Buch — raamat</div><div class=\"kurss-example\">hängen — rippuma</div><div class=\"kurss-example\">das Bild — pilt</div><div class=\"kurss-example\">ein Bild — pilt</div><div class=\"kurss-example\">die Tafel — tahvel</div><div class=\"kurss-example\">eine Tafel — tahvel</div><div class=\"kurss-example\">wie — milline</div><div class=\"kurss-example\">ist — on</div><div class=\"kurss-example\">dick — paks</div><div class=\"kurss-example\">das Heft — vihik</div><div class=\"kurss-example\">ein Heft — vihik</div><div class=\"kurss-example\">dünn — õhuke</div><div class=\"kurss-example\">niedrig — madal</div><div class=\"kurss-example\">hoch — kõrge</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Hääldus</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Garo ī skaņu vācu valodā apzīmē ar ie: liegen (līgen), hier (hīr), wie (vī).</div><div class=\"kurss-example\">ck ir divkāršs k: dick (dikk).</div><div class=\"kurss-example\">Omadus- ja määrsõnades kõlab lõpp -ig nagu kerge -ich: niedrig (niidrih).</div><div class=\"kurss-example\">Ja galotne -ig lõpeb e-ga: -ige, siis hääldatakse g selge g-häälikuna: niedrige (niidrige) Bänke.</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatika</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Lause alus</h4><div class=\"lesson1-grammar-note\">Lause alus vastab saksa keeles küsimusele wer? / was? ja seisab nominatiivis.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wer? küsib inimeste kohta.</div><div class=\"kurss-example\">Ar was? jautā pēc priekšmetiem.</div><div class=\"kurss-example\">Wer singt? — Sie singt.</div><div class=\"kurss-example\">Was liegt hier? — Hier liegt ein Buch.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Artiklid</h4><div class=\"lesson1-grammar-note\">Saksa keeles on nimisõnal 3 sugu: meessugu, naissugu ja kesksugu. Nimisõna ees seisab tavaliselt sõnake, mida nimetatakse artikliks. Seda sõnakest ei tõlgita.</div><h5 class=\"lesson2-subtitle\">Noteiktais artikuls</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">meessugu — der</div><div class=\"kurss-example\">naissugu — die</div><div class=\"kurss-example\">vidējā kārta — das</div><div class=\"kurss-example\">Mitmuses on kõigi kolme soo määrav artikkel die.</div><div class=\"kurss-example\">der Tisch — die Tische</div><div class=\"kurss-example\">die Bank — die Bänke</div><div class=\"kurss-example\">das Heft — die Hefte</div></div><h5 class=\"lesson2-subtitle\">Nenoteiktais artikuls</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">meessugu — ein</div><div class=\"kurss-example\">naissugu — eine</div><div class=\"kurss-example\">vidējā kārta — ein</div><div class=\"kurss-example\">Nenoteiktajam artikulam daudzskaitļa nav.</div><div class=\"kurss-example\">ein Tisch — Tische</div><div class=\"kurss-example\">ein Heft — Hefte</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Pärisnimed</h4><div class=\"lesson1-grammar-note\">Pärisnimede ees artiklit ei kasutata.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans spielt, aber Marie singt.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Tegusõna koht</h4><div class=\"lesson1-grammar-note\">Jutustavas lauses seisab tegusõna teisel kohal.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier hängt eine Karte.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>stehen / liegen / hängen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Vāciski par priekšmetiem, kas stāv vertikāli, saka, ka priekšmets stāv:<br>der Tisch steht<br>die Bank steht</div><div class=\"kurss-example\">Par priekšmetiem, kas atrodas horizontālā stāvoklī, saka, ka tie guļ:<br>das Buch liegt<br>das Heft liegt</div><div class=\"kurss-example\">Priekšmeti var arī karāties:<br>die Karte hängt<br>die Tafel hängt</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Tõlgi</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson3-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"3. õppetunni tõlkekaart\"><span class=\"lesson1-training-progress\">3. õppetund · Tõlgi: 1 / 22</span><span class=\"lesson1-training-text\">Kas sina arvutad?</span></button><p class=\"lesson1-training-hint\">Klõpsa kaardil, et näha saksakeelset tõlget. Pärast vastust näitab järgmine klõps uut kaarti.</p></div></div></details>\n",
  "kurssLesson4": "            <h3>4. õppetund</h3>\n            <p class=\"kurss-lesson-intro\">Akusatiiv, nehmen, hinlegen, hinausgehen ja omadussõnad.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialoogid / laused</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Paul kommt und nimmt einen Federhalter.</div><div class=\"kurss-example\">Er zeigt den Federhalter.</div><div class=\"kurss-example\">Er fragt: „Wie ist der Federhalter?“</div><div class=\"kurss-example\">Olga antwortet: „Der Federhalter ist schwarz.“</div><div class=\"kurss-example\">Ist der Federhalter weiß? Nein, der Federhalter ist nicht weiß, er ist schwarz.</div><div class=\"kurss-example\">Marie kommt und nimmt eine Feder.</div><div class=\"kurss-example\">Sie fragt: „Wie ist die Feder?“</div><div class=\"kurss-example\">Olga antwortet: „Die Feder ist spitz.“</div><div class=\"kurss-example\">Ist die Feder stumpf? Nein, die Feder ist nicht stumpf, sie ist spitz.</div><div class=\"kurss-example\">Was legt das Mädchen hin? Es legt die Feder hin.</div><div class=\"kurss-example\">Was nimmst du? Ich nehme ein Messer.</div><div class=\"kurss-example\">Wie ist das Messer? Das Messer ist scharf.</div><div class=\"kurss-example\">Ist das Messer stumpf? Nein, es ist nicht stumpf, es ist scharf.</div><div class=\"kurss-example\">Was legst du hin? Ich lege das Messer, die Feder und den Federhalter hin.</div><div class=\"kurss-example\">Dann gehe ich hinaus und arbeite.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Sõnad</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">nehmen (nēmen) — võtma</div><div class=\"kurss-example\">er nimmt (nimt) — tema võtab</div><div class=\"kurss-example\">der Federhalter (dēr fēderhalter) — sulepea</div><div class=\"kurss-example\">einen Federhalter — sulepead</div><div class=\"kurss-example\">zeigen — näitama</div><div class=\"kurss-example\">schwarz (švarc) — must</div><div class=\"kurss-example\">weiß (veis) — valge</div><div class=\"kurss-example\">die Feder (dī fēder) — sulg</div><div class=\"kurss-example\">eine Feder — sulge</div><div class=\"kurss-example\">spitz (špic) — terav</div><div class=\"kurss-example\">hinlegen — maha panema</div><div class=\"kurss-example\">legt hin — paneb maha</div><div class=\"kurss-example\">das Mädchen (mētchen) — tüdruk</div><div class=\"kurss-example\">das Messer — nuga</div><div class=\"kurss-example\">ein Messer — nuga</div><div class=\"kurss-example\">scharf — terav</div><div class=\"kurss-example\">stumpf (štumpf) — nüri</div><div class=\"kurss-example\">dann — siis</div><div class=\"kurss-example\">hinaus — välja</div><div class=\"kurss-example\">hinausgehen — välja minema</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Hääldus</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Galotnes -en, -er, -el on rõhutamata, seetõttu on e neis lõppudes nõrgalt kuuldav: kommen, nehmen, der Federhalter.</div><div class=\"kurss-example\">h võib saksa keeles olla nii häälik kui ka eelneva vokaali pikkuse märk.</div><div class=\"kurss-example\">Ja h ir garumzīme, to neizrunā kā skaņu: nehmen (nēmen).</div><div class=\"kurss-example\">Ja patskanim seko tikai viens līdzskanis, patskani izrunā gari: die (dī) Feder (fēder), den (dēn).</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatika</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Akusatiiv</h4><div class=\"lesson1-grammar-note\">Naissoos ja kesksoos on akusatiiv sama, mis nominatiiv. Muutub ainult meessugu.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Nominativ: ein Federhalter, eine Feder, ein Messer.</div><div class=\"kurss-example\">Akkusativ: einen Federhalter, eine Feder, ein Messer.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>nehmen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich nehme</div><div class=\"kurss-example\">du nimmst</div><div class=\"kurss-example\">er/sie nimmt</div><div class=\"kurss-example\">wir nehmen</div><div class=\"kurss-example\">ihr nehmt</div><div class=\"kurss-example\">sie nehmen</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Asesõnad</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er — meessugu</div><div class=\"kurss-example\">sie — naissugu</div><div class=\"kurss-example\">es — kesksugu</div><div class=\"kurss-example\">mitmuses — sie</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Lahutatavad tegusõnad</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">hinlegen → ich lege das Messer hin</div><div class=\"kurss-example\">hinausgehen → Marie geht hinaus</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>Omadussõnad</h4><div class=\"lesson1-grammar-note\">Kui omadussõna on lauses öeldistäide, ei muutu see ei soo ega arvu järgi.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist klein</div><div class=\"kurss-example\">die Feder ist klein</div><div class=\"kurss-example\">das Messer ist klein</div><div class=\"kurss-example\">die Messer sind klein</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>6</span>Eitus sõnaga nicht</h4><div class=\"lesson1-grammar-note\">Kui nicht eitab omadussõna, seisab see eitatava sõna ees.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist nicht weiß</div><div class=\"kurss-example\">das Messer ist nicht scharf</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>7</span>-chen / -lein</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Lõppudega -chen ja -lein nimisõnad on kesks soost: das Mädchen.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Tõlgi</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson4-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"4. õppetunni tõlkekaart\"><span class=\"lesson1-training-progress\">4. õppetund · Tõlgi: 1 / 16</span><span class=\"lesson1-training-text\">Tüdruk võtab sulepea.</span></button><p class=\"lesson1-training-hint\">Klõpsa kaardil, et näha saksakeelset tõlget. Pärast vastust näitab järgmine klõps uut kaarti.</p></div></div></details>\n",
  "kurssLesson5": "\n    <h3>5. õppetund</h3>\n    <p class=\"kurss-lesson-intro\">Wen?, akusatiiv, sitzen, fragen ja -in lõpp.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialoogid / laused</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">Wer sitzt und fragt? Der Lehrer sitzt und fragt.</div>\n        <div class=\"kurss-example\">Wer steht und antwortet? Der Schüler steht und antwortet.</div>\n        <div class=\"kurss-example\">Wie antwortet der Schüler? Der Schüler antwortet gut.</div>\n        <div class=\"kurss-example\">Wen lobt der Lehrer? Der Lehrer lobt den Schüler.</div>\n        <div class=\"kurss-example\">Wie ist der Schüler? Der Schüler ist klein.</div>\n        <div class=\"kurss-example\">Ist der Schüler klein oder groß? Er ist klein.</div>\n        <div class=\"kurss-example\">Wen fragt die Lehrerin? Die Lehrerin fragt die Schülerin.</div>\n        <div class=\"kurss-example\">Wie antwortet die Schülerin? Die Schülerin antwortet schlecht.</div>\n        <div class=\"kurss-example\">Was tut die Lehrerin? Sie tadelt die Schülerin.</div>\n        <div class=\"kurss-example\">Die Schülerin ist nicht klein, sie ist groß.</div>\n        <div class=\"kurss-example\">Ein Kind spielt. Das Kind ist artig.</div>\n        <div class=\"kurss-example\">Die Mutter liebt das Kind. Der Vater lobt das Kind.</div>\n      </div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Sõnad</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">sitzen (zicen) — istuma</div>\n        <div class=\"kurss-example\">fragen (frāgen) — küsima</div>\n        <div class=\"kurss-example\">der Lehrer (dēr lērer) — õpetaja</div>\n        <div class=\"kurss-example\">gut (gūt) — hästi</div>\n        <div class=\"kurss-example\">wen (vēn) — keda</div>\n        <div class=\"kurss-example\">loben — kiitma</div>\n        <div class=\"kurss-example\">der Schüler (šūler) — õpilane</div>\n        <div class=\"kurss-example\">klein — väike</div>\n        <div class=\"kurss-example\">groß (grōs) — suur</div>\n        <div class=\"kurss-example\">die Lehrerin — õpetajanna</div>\n        <div class=\"kurss-example\">die Schülerin — õpilane (naine)</div>\n        <div class=\"kurss-example\">schlecht (šleht) — halvasti</div>\n        <div class=\"kurss-example\">tadeln — laitma</div>\n        <div class=\"kurss-example\">oder (ōder) — või</div>\n        <div class=\"kurss-example\">das Kind (kint) — laps</div>\n        <div class=\"kurss-example\">artig (ārtich) — sõnakuulelik</div>\n        <div class=\"kurss-example\">die Mutter — ema</div>\n        <div class=\"kurss-example\">lieben (līben) — armastama</div>\n        <div class=\"kurss-example\">der Vater (fāter) — isa</div>\n      </div></div>\n    </details>\n\n        <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Hääldus</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">tz on kahekordne z-häälik ja seda hääldatakse nagu z-i: sitzen (zicen).</div>\n        <div class=\"kurss-example\">v vācu vārdos izrunā kā f: der Vater (fāter).</div>\n        <div class=\"kurss-example\">ß nimetatakse Eszettiks ja seda hääldatakse nagu s-i: groß (groos), weiß (vais).</div>\n      </div></div>\n    </details>\n\n<details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatika</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Nominatiiv ja akusatiiv</h4><div class=\"lesson1-grammar-note\">Eesti keeles vastab nominatiiv küsimusele kes/mis?, aga akusatiiv küsimusele keda/mida?.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Saksa keeles on nominatiivis inimeste kohta küsimus wer? ja esemete kohta was?.</div><div class=\"kurss-example\">Akusatiivis küsitakse inimeste kohta wen? ja esemete kohta was?</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Artikli muutumine akusatiivis</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Akkusativ: den Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">sitzen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich sitze</div><div class=\"kurss-example\">du sitzt</div><div class=\"kurss-example\">er/sie/es sitzt</div><div class=\"kurss-example\">wir sitzen</div><div class=\"kurss-example\">ihr sitzt</div><div class=\"kurss-example\">sie sitzen</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">fragen + akusatiiv</h4><div class=\"lesson1-grammar-note\">Tegusõna fragen nõuab saksa keeles akusatiivi.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wen fragt der Lehrer?</div><div class=\"kurss-example\">Der Lehrer fragt den Schüler.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">-in lõpp</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Paljud naissoost isikut tähistavad nimisõnad moodustatakse lõpuga -in.</div><div class=\"kurss-example\">die Lehrerin</div><div class=\"kurss-example\">die Schülerin</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Tegusõna koht</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Stāstāmā teikumā darbības vārds stāv otrā vietā.</div><div class=\"kurss-example\">Dann geht das Mädchen hinaus und arbeitet.</div><div class=\"kurss-example\">Das Mädchen geht dann hinaus und arbeitet.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Tõlgi</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson5-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"5. õppetunni tõlkekaart\"><span class=\"lesson1-training-progress\">5. õppetund · Tõlgi: 1 / 16</span><span class=\"lesson1-training-text\">Keda armastab isa?</span></button><p class=\"lesson1-training-hint\">Klõpsa kaardil, et näha saksakeelset tõlget. Pärast vastust näitab järgmine klõps uut kaarti.</p></div></div>\n    </details>\n  ",
  "kurssLesson6": "\n    <h3>6. õppetund</h3>\n    <p class=\"kurss-lesson-intro\">Arvsõnad, mitmus, täishäälikumuutused ja nimisõnade mitmuse vormid.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialoogid / laused</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier liegt ein Bleistift.</div><div class=\"kurss-example\">Dort liegen einige Messer.</div><div class=\"kurss-example\">Edgar nimmt ein Messer, zwei Messer, drei Messer.</div><div class=\"kurss-example\">Er legt die Messer wieder hin.</div><div class=\"kurss-example\">Alle Messer sind scharf.</div><div class=\"kurss-example\">Dann nimmt er wieder ein Messer.</div><div class=\"kurss-example\">Er macht das Messer auf.</div><div class=\"kurss-example\">Er nimmt den Bleistift.</div><div class=\"kurss-example\">Er spitzt den Bleistift an.</div><div class=\"kurss-example\">Er legt das Messer hin.</div><div class=\"kurss-example\">Er setzt sich und zeichnet.</div><div class=\"kurss-example\">Was zeichnet er? Er zeichnet einen Schlüssel.</div><div class=\"kurss-example\">Gertrud zeichnet ein Fenster und eine Tafel.</div><div class=\"kurss-example\">Anna zeichnet einen Garten.</div><div class=\"kurss-example\">Hier liegen vier Löffel.</div><div class=\"kurss-example\">Dort liegen fünf Nadeln.</div><div class=\"kurss-example\">Gertrud kommt und zählt die Löffel: das ist ein Löffel; das sind zwei, drei, vier Löffel.</div><div class=\"kurss-example\">Anna zählt die Nadeln: das ist eine Nadel; das sind zwei, drei, vier, fünf Nadeln.</div><div class=\"kurss-example\">Wieviel Nadeln sind hier?</div><div class=\"kurss-example\">Hier ist eine Nadel.</div><div class=\"kurss-example\">Dort sind zwei, drei, vier Nadeln.</div><div class=\"kurss-example\">Fünf Schlüssel sind hier.</div><div class=\"kurss-example\">Sechs Löffel sind dort.</div><div class=\"kurss-example\">Was ist das?</div><div class=\"kurss-example\">Das ist ein Hammer. Das sind fünf Hämmer.</div><div class=\"kurss-example\">Das ist ein Deckel. Das sind sechs Deckel.</div><div class=\"kurss-example\">Das ist ein Eimer. Das sind sieben Eimer.</div><div class=\"kurss-example\">Das ist ein Teller. Das sind acht Teller.</div><div class=\"kurss-example\">Das ist ein Wagen. Das sind neun Wagen.</div><div class=\"kurss-example\">Das ist ein Schlitten. Das sind zehn Schlitten.</div><div class=\"kurss-example\">Wie sind die Dinge?</div><div class=\"kurss-example\">Der Hammer ist klein. Die Hämmer sind klein.</div><div class=\"kurss-example\">Der Deckel ist groß. Die Deckel sind groß.</div><div class=\"kurss-example\">Der Eimer ist voll. Die Eimer sind voll.</div><div class=\"kurss-example\">Der Teller ist leer. Die Teller sind leer.</div><div class=\"kurss-example\">Der Wagen ist schwer. Die Wagen sind schwer.</div><div class=\"kurss-example\">Der Schlitten ist leicht. Die Schlitten sind leicht.</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Sõnad</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">liegt — asub, on, lamab</div><div class=\"kurss-example\">der Bleistift (bleištift) — pliiats</div><div class=\"kurss-example\">einige (einige) — mõned</div><div class=\"kurss-example\">hinlegen — maha panema</div><div class=\"kurss-example\">legt hin — paneb maha</div><div class=\"kurss-example\">wieder (vīder) — jälle</div><div class=\"kurss-example\">aufmachen — avama</div><div class=\"kurss-example\">er macht auf — tema avab</div><div class=\"kurss-example\">anspitzen (anšpicen) — teritama</div><div class=\"kurss-example\">er spitzt an — tema teritab</div><div class=\"kurss-example\">sich setzen — maha istuma</div><div class=\"kurss-example\">setzt sich — istub maha</div><div class=\"kurss-example\">der Schlüssel (šlūsel) — võti</div><div class=\"kurss-example\">das Fenster (fenster) — aken</div><div class=\"kurss-example\">die Tafel (dī tāfel) — tahvel</div><div class=\"kurss-example\">der Garten — aed</div><div class=\"kurss-example\">der Löffel — lusikas</div><div class=\"kurss-example\">zählen (cēlen) — loendama</div><div class=\"kurss-example\">die Nadel — nõel</div><div class=\"kurss-example\">was ist das — mis see on?</div><div class=\"kurss-example\">der Hammer — haamer</div><div class=\"kurss-example\">die Hämmer — haamrid</div><div class=\"kurss-example\">der Deckel (dēr dekel) — kaas</div><div class=\"kurss-example\">der Teller — taldrik</div><div class=\"kurss-example\">der Wagen — vanker</div><div class=\"kurss-example\">der Schlitten — kelk</div><div class=\"kurss-example\">das Ding — asi</div><div class=\"kurss-example\">die Dinge — asjad</div><div class=\"kurss-example\">wie sind die Dinge? — millised on asjad?</div><div class=\"kurss-example\">voll (fōl) — täis</div><div class=\"kurss-example\">leer (lēr) — tühi</div><div class=\"kurss-example\">schwer (švēr) — raske</div><div class=\"kurss-example\">leicht — kerge</div><div class=\"kurss-example\">der Eimer — ämber</div><div class=\"kurss-example\">wieviel (vīfīl) — kui palju</div><div class=\"kurss-example\">wieviel Nadeln — kui palju nõelu</div><div class=\"kurss-example\">hier (hiir) — siin</div><div class=\"kurss-example\">dort — seal</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Hääldus</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ä on vokaali a muutunud variant ning seda hääldatakse lühikese või pika kitsa e-na.</div><div class=\"kurss-example\">Näited: das Mädchen (mētchen), die Bänke (dī benke), der Vater (dēr fāter), die Väter (dī fēter).</div><div class=\"kurss-example\">ü ir patskaņa u pārskanojums. To izrunājot, lūpas ļoti jāapaļo un jāmēģina ar apaļi veidotām lūpām izrunāt i.</div><div class=\"kurss-example\">Näited: fünf, der Schlüssel (šlūsel).</div><div class=\"kurss-example\">ö izrunā ar apaļi veidotām lūpām, mēģinot izrunāt e: der Löffel.</div><div class=\"kurss-example\">Kahekordne täishäälik tähistab pikka täishäälikut: leer (leer).</div><div class=\"kurss-example\">Diftongi eu hääldatakse nagu oi: neun (noin).</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatika</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Grammatika ja selgitused</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Liitverbi rõhuline eesliide eraldub olevikus verbist ja paikneb lause lõpus.</div><div class=\"kurss-example\">Näited: hinlegen — er legt hin; aufmachen — er macht auf; anspitzen — er spitzt an.</div><div class=\"kurss-example\">Arvsõnal üks on nimisõnaga kasutades saksa keeles kolm soovormi: meessoos ein, naissoos eine, kesksoos ein.</div><div class=\"kurss-example\">Näited: ein Schüler — üks õpilane; eine Schülerin — üks õpilane (naine); ein Kind — üks laps.</div><div class=\"kurss-example\">Arvud: eins, zwei, drei, vier (fīr), fünf, sechs (zeks), sieben (zīben), acht, neun (noin), zehn (cēn).</div><div class=\"kurss-example\">Saksa keeles on sidusverbil sein ainsuse ja mitmuse vorm: der Schüler ist klein; die Schüler sind klein.</div><div class=\"kurss-example\">Eesti keeles on ainsuses see ja mitmuses need; saksa keeles kasutatakse sellistes konstruktsioonides vorme das ist ja das sind.</div><div class=\"kurss-example\">Näited: see on haamer — das ist ein Hammer; see on nõel — das ist eine Nadel; need on haamrid — das sind Hämmer; need on nõelad — das sind Nadeln.</div><div class=\"kurss-example\">Der Wagen — Der Wagen (vanker) ja der Schlitten (kelk) on saksa keeles nii ainsuses kui mitmuses kasutatavad tavalised nimisõnad.</div><div class=\"kurss-example\">Mees- ja kesksoost nimisõnad lõpuga -er, -el, -en ei saa mitmuses sageli lõppu.</div><div class=\"kurss-example\">Näited: der Hammer — die Hämmer; der Garten — die Gärten; das Fenster — die Fenster; das Messer — die Messer.</div><div class=\"kurss-example\">Naissoost nimisõnad lõpuga -el, -er saavad mitmuses lõpu -n.</div><div class=\"kurss-example\">Näited: die Nadel — die Nadeln; die Feder — die Federn.</div><div class=\"kurss-example\">Erandid: die Mutter (ema) — die Mütter (emad); die Tochter (tütar) — die Töchter (tütred).</div><div class=\"kurss-example\">Nenoteiktajam artikulam daudzskaitļa nav: das ist ein Wagen — das sind Wagen; das ist eine Nadel — das sind Nadeln.</div><div class=\"kurss-example\">Stāstāmā teikumā izteicējs-tegusõna teisel kohal: er legt den Schlüssel hin; dann legt er den Schlüssel hin.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Tõlgi</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson6-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"6. õppetunni tõlkekaart\"><span class=\"lesson1-training-progress\">6. õppetund · Tõlgi: 1 / 21</span><span class=\"lesson1-training-text\">Paul võtab pliiatsi ja joonistab.</span></button><p class=\"lesson1-training-hint\">Klõpsa kaardil, et näha saksakeelset tõlget. Pärast vastust näitab järgmine klõps uut kaarti.</p></div></div>\n    </details>\n  ",
  "kurssLesson7": "            <h3>7. õppetund</h3>\n            <p class=\"kurss-lesson-intro\">Seitsmes õppetund: käskiv kõneviis, viisakusvorm ja mitmus.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialoogid / laused</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans, singe ein Lied! Was tust du? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans und Olga, singt ein Lied! Was tut ihr? Wir singen ein Lied.</div><div class=\"kurss-example\">Fräulein Müller, singen Sie, bitte, ein Lied! Was tun Sie? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans, zähle die Teller! Was tut Hans? Er zählt die Teller.</div><div class=\"kurss-example\">Hans und Olga, zählt die Teller! Was tun Hans und Olga? Sie zählen die Teller.</div><div class=\"kurss-example\">Fräulein Müller, zählen Sie, bitte, die Teller!</div><div class=\"kurss-example\">Hans, öffne das Fenster! Was tut Hans? Er öffnet das Fenster.</div><div class=\"kurss-example\">Hans und Olga, öffnet die Fenster! Was tun Hans und Olga? Sie öffnen die Fenster.</div><div class=\"kurss-example\">Fräulein Müller, öffnen Sie, bitte, alle Fenster!</div><div class=\"kurss-example\">Fräulein Müller öffnet alle Fenster.</div><div class=\"kurss-example\">Das ist der Spiegel. Das sind die Spiegel.</div><div class=\"kurss-example\">Das ist der Lappen. Das sind die Lappen.</div><div class=\"kurss-example\">Das ist der Spaten. Das sind die Spaten.</div><div class=\"kurss-example\">Das ist der Besen. Das sind die Besen.</div><div class=\"kurss-example\">Das ist die Schaufel. Das sind die Schaufeln.</div><div class=\"kurss-example\">Das ist die Schüssel. Das sind die Schüsseln.</div><div class=\"kurss-example\">Das ist das Zimmer. Das sind die Zimmer.</div><div class=\"kurss-example\">Das ist das Ufer. Das sind die Ufer.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Sõnad</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">singen — laulma</div><div class=\"kurss-example\">singe — laula</div><div class=\"kurss-example\">singt — laulge</div><div class=\"kurss-example\">singen Sie — laulge</div><div class=\"kurss-example\">das Lied (das līt) — laul</div><div class=\"kurss-example\">Sie — Teie</div><div class=\"kurss-example\">zählen — lugema</div><div class=\"kurss-example\">das Fräulein (froilein) — preili</div><div class=\"kurss-example\">der Müller — mölder</div><div class=\"kurss-example\">öffnen — avama</div><div class=\"kurss-example\">das Fenster (fenster) — aken</div><div class=\"kurss-example\">alle — kõik</div><div class=\"kurss-example\">der Spiegel (špīgel) — peegel</div><div class=\"kurss-example\">der Lappen — lapp</div><div class=\"kurss-example\">der Spaten — labidas</div><div class=\"kurss-example\">der Besen — luud</div><div class=\"kurss-example\">die Schaufel — kühvel</div><div class=\"kurss-example\">die Schüssel — kauss</div><div class=\"kurss-example\">das Zimmer — tuba</div><div class=\"kurss-example\">das Ufer (ūfer) — kallas</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Hääldus</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Sõna või silbi alguses hääldatakse sp nagu šp: der Spiegel (dēr špīgel).</div><div class=\"kurss-example\">sch hääldatakse nagu š: die Schaufel (dī šaufel), die Schüssel (dī šūsel).</div><div class=\"kurss-example\">Diftongi äu hääldatakse nagu oi: das Fräulein (das froilein).</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatika</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Käskiv kõneviis</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Ainsuse 2. isiku käskiv kõneviis vastab verbi ainsuse 2. isikule ilma isikulõputa -st, millele lisatakse lõpp -e.</div><div class=\"kurss-example\">Näited: antworte!, arbeite!, öffne!, zeichne!</div><div class=\"kurss-example\">Ļoti bieži galotne -e ei kasutata, kui käskiv vorm muutub sellega üherõhuliseks: geh!, steh!, komm!, tu!, sing!, frag!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Mitmuse käskiv kõneviis</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Käskiva kõneviisi mitmuse 2. isiku vorm sarnaneb oleviku mitmuse 2. isiku vormiga, kuid seda kasutatakse ilma asesõnata.</div><div class=\"kurss-example\">Näited: antwortet!, arbeitet!, öffnet!, zeichnet!, geht!, steht!, tut!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Viisakusvorm sõnaga Sie</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Uzrunas forma ar “Jūs” līdzinās daudzskaitļa 3. personai. Vietniekvārds Sie rakstāms ar lielo burtu un stāv pēc darbības vārda.</div><div class=\"kurss-example\">Näited: antworten Sie!, arbeiten Sie!, öffnen Sie!, zeichnen Sie!, gehen Sie!, stehen Sie!, tun Sie!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>öffnen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Tegusõnal öffnen lisatakse häälduse hõlbustamiseks ainsuse 2. ja 3. isikus ning mitmuse 2. isikus tüve ja lõpu vahele e: du öffnest, er öffnet, ihr öffnet.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Harjutus</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson7-exercise-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"7. õppetunni harjutuskaart\"><span class=\"lesson1-training-progress\">7. õppetund · Übung: 1 / 16</span><span class=\"lesson1-training-text\">fragen — küsima</span></button><p class=\"lesson1-training-hint\">Puuduta kaarti, et näha käskiva kõneviisi vorme.</p></div></div></details>\n"
};

